class.description:
[SourcePPVTF] exposes a first-cut wrapper over SourcePP's VTF support for scripts.
It can open existing VTF files, create new ones from Godot [Image] data, inspect core metadata, decode texture contents to [Image], and bake the VTF back to bytes or disk.
Decoded images are currently returned as [code]Image.FORMAT_RGBA8[/code] regardless of the VTF's internal storage format.
[codeblock]
var image := Image.load_from_file("user://albedo.png")
var vtf := SourcePPVTF.new()
if vtf.create_from_image(image, 4, true) != OK:
	return

vtf.set_format(SourcePPVTF.FORMAT_DXT5)
# Use set_format_with_quality() when the encoder accepts a quality parameter.
vtf.save("user://albedo.vtf")

var reopened := SourcePPVTF.new()
if reopened.open("user://albedo.vtf") == OK:
	var decoded := reopened.get_image()
	decoded.save_png("user://albedo_preview.png")
[/codeblock]
